    "인증키가 날씨 조회에 쓰일 수 없어요. 공공데이터포털에서 '기상청_단기예보 조회서비스' 활용신청을 확인해 주세요. 승인 직후라면 반영까지 1~2시간 걸릴 수 있어요.": "This key can't be used for weather. Check your data.go.kr application for the KMA short-term forecast service (기상청_단기예보 조회서비스). New approvals can take 1–2 hours to take effect.",
    "인증키가 지난 날씨 조회에 쓰일 수 없어요. 공공데이터포털에서 '기상청_지상(종관, ASOS) 일자료 조회서비스' 활용신청을 확인해 주세요. 승인 직후라면 반영까지 1~2시간 걸릴 수 있어요.": "This key can't be used for past weather. Check your data.go.kr application for the KMA ASOS daily data service (기상청_지상(종관, ASOS) 일자료 조회서비스). New approvals can take 1–2 hours to take effect.",
    "인증키가 공휴일 조회에 쓰일 수 없어요. 공공데이터포털에서 '한국천문연구원_특일 정보' 활용신청을 확인해 주세요. 승인 직후라면 반영까지 1~2시간 걸릴 수 있어요.": "This key can't be used for public holidays. Check your data.go.kr application for the KASI special days service (한국천문연구원_특일 정보). New approvals can take 1–2 hours to take effect.",
