    "배의 실시간 위치나 결항 소식이 아니라 운항 시간표예요. 점선은 두 항구를 곧게 이은 그림이고 실제 뱃길과 다릅니다. 기상에 따라 결항될 수 있으니 떠나기 전에 선사에 확인하세요.": "This is a timetable, not live ship positions or cancellation news. Dashed lines simply connect the two ports and are not the real sea route. Sailings can be cancelled due to weather — check with the operator before you go.",
    "출처: 국가대중교통정보센터(TAGO) · 항구 위치: © OpenStreetMap": "Source: TAGO (Korea transit info) · Port locations: © OpenStreetMap",
