    "항구의 여객선 시간표를 지도에 뱃길 선으로 펼칩니다.": "Shows a port's ferry timetable as routes on the map.",
    "인증키가 여객선 시간표에 쓰일 수 없어요. 공공데이터포털에서 '국토교통부_(TAGO)_국내선박운항정보' 활용신청을 확인해 주세요. 승인 직후라면 반영까지 시간이 걸릴 수 있어요.": "The service key can't be used for ferry timetables. Check your data.go.kr application for 'MOLIT (TAGO) domestic ship operation info'. It can take a while right after approval.",
