    "인증키가 버스 도착 정보에 쓰일 수 없어요. 공공데이터포털에서 TAGO 버스도착정보 활용신청을 확인해 주세요. 승인 직후라면 반영까지 시간이 걸릴 수 있어요.": "The service key was rejected for bus arrivals. Check on data.go.kr that it is approved for TAGO bus arrival information. New approvals can take a while to take effect.",
