    "인증키가 이 조회에 쓰일 수 없어요. 공공데이터포털에서 TAGO 버스노선정보·버스위치정보 활용신청을 확인해 주세요. 승인 직후라면 반영까지 시간이 걸릴 수 있어요.": "The service key was rejected for this request. Check on data.go.kr that it is approved for both TAGO bus route and bus location information. New approvals can take a while to take effect.",
