    // Editing controls, help and dynamically generated UI.
    "✎ 제자리 편집 — 보이는 그대로 고쳐요. Enter 로 문단을 나누고, 빈 문단에서 Backspace 로 지웁니다. 글자를 드래그하면 그 부분만 서식을 바꾸고, 문단을 우클릭하면 문단·목록·표·페이지·머리글/바닥글·그림 편집 메뉴가 열립니다. 손대지 않은 곳은 저장할 때 바이트 그대로 남습니다.": "✎ Edit in place. Press Enter to split a paragraph or Backspace in an empty paragraph to delete it. Select text to format it, or right-click a paragraph for paragraph, list, table, page, header/footer and image commands. Unchanged content is preserved byte for byte when saving.",
    "✎ 문단 목록 — 글자만 고치는 간이 표시예요. 글꼴·여백·쪽 나눔은 실제 문서와 다르게 보입니다. 손대지 않은 곳의 서식은 저장할 때 그대로 유지됩니다.": "✎ Paragraph list — a simplified view for editing text. Fonts, margins and page breaks may differ from the document. Formatting in unchanged areas is preserved when saving.",
