    "PDF에 추가한 편집/핀을 버리고 원본 파일을 다시 읽을까요?": "Discard the edits/pins added to the PDF and reload the original file?",
    "드래그: 탭바에서 위치 변경": "Drag: reorder in the tab bar",
    "본문 좌우로 끌면 분할": "drag to the left/right of the page to split",
    "탭이 하나일 때는 분할 드래그 안 됨": "can't split while only one tab is open",
    "우클릭: 탭 정리": "right-click: tidy tabs",
    "원본 폴더에 접근하지 못했어요.": "Couldn't access the original folder.",
    "원본 파일 이름을 바꿀 권한이 없어요.": "No permission to rename the original file.",
    "디스크에 있는 원본 파일 이름이 실제로 바뀝니다.": "This renames the original file on disk.",
    "같은 폴더에 동일한 이름의 파일이 이미 있어요.": "A file with the same name already exists in this folder.",
    "이 환경에서는 대소문자만 바꾸는 이름 변경을 지원하지 않아요.": "Renaming that only changes letter case isn't supported here.",
    "원본 파일 이름을 바꾸지 못했어요. 기존 파일은 유지됩니다.": "Couldn't rename the original file. The existing file is kept.",
    "이 파일은 앱에서 지울 수 없어요. '열기 → 폴더 열기'로 연 파일만 디스크에서 지울 수 있어요.": "This file can't be deleted from the app. Only files opened with 'Open → Open folder' can be deleted from disk.",
    "선택한 파일 중 디스크에서 지울 수 있는 것이 없어요. '열기 → 폴더 열기'로 연 파일만 지울 수 있어요.": "None of the selected files can be deleted from disk. Only files opened with 'Open → Open folder' can be deleted.",
    "완전히 지우기": "Delete permanently",
    "지우지 못했어요. 파일이 다른 프로그램에서 열려 있거나 권한이 없을 수 있어요.": "Couldn't delete. The file may be open in another program, or you may not have permission.",
