    "SQL 실행": "Run SQL",
    "이 데이터베이스는 읽기 전용으로 열렸습니다. SQL 실행과 데이터 변경은 안전을 위해 ClassDock 저장 폴더에 있는 DB 파일에서만 사용할 수 있습니다.": "This database was opened read-only. For safety, running SQL and changing data only work on DB files in the ClassDock save folder.",
