    "임의 SQL(SELECT·INSERT·UPDATE·DELETE·DDL) · 수정 시 자동 .bak 백업": "Any SQL (SELECT·INSERT·UPDATE·DELETE·DDL) · automatic .bak backup on changes",
    "예) INSERT INTO 학생(이름, 점수) VALUES ('홍길동', 90);": "e.g. INSERT INTO students(name, score) VALUES ('Alex', 90);",
