    "실행할 SQL을 입력하세요": "Enter SQL to run",
    "SQL 실행에 실패했습니다.": "Running the SQL failed.",
    "이 도구는 변경을 실행할 때마다 자동으로 커밋하고 .bak 백업을 만듭니다. COMMIT·BEGIN·ROLLBACK 같은 트랜잭션 명령이나 ATTACH·DETACH는 직접 쓸 수 없습니다. INSERT·UPDATE·DELETE·DDL만 그대로 실행하면 됩니다.": "This tool commits automatically and makes a .bak backup each time it runs a change. Transaction commands such as COMMIT·BEGIN·ROLLBACK and ATTACH·DETACH can't be used directly. Just run INSERT·UPDATE·DELETE·DDL as they are.",
    "HWPX를 열지 못했어요. 배포용(DRM)·암호 문서이거나 손상된 파일일 수 있어요.": "Couldn't open the HWPX. It may be a distribution (DRM) or password-protected document, or the file may be damaged.",
    "문서 그림": "Document image",
    "HWPX 내용을 읽지 못했어요. 배포용(DRM) 문서일 수 있어요 — 한글에서 'PDF로 저장' 후 열어주세요.": "Couldn't read the HWPX content. It may be a distribution (DRM) document — save it as PDF in Hangul, then open that.",
    "HWPX 간이 미리보기 — 문단·표·그림과 기본 서식만 보여줘요. 정확한 모양이 필요하면 한글에서 'PDF로 저장' 후 열어주세요.": "Simple HWPX preview — shows paragraphs, tables, images and basic formatting only. For the exact layout, save as PDF in Hangul and open that.",
    "HWPX 텍스트 미리보기 — 본문 구조를 읽지 못해 문서에 저장된 텍스트만 보여줘요.": "HWPX text preview — the body structure couldn't be read, so only the stored text is shown.",
    "암호로 보호된 .doc 이라 열 수 없어요. Word에서 암호를 풀고 다시 저장한 뒤 열어주세요.": "This .doc is password-protected and can't be opened. Remove the password in Word, save it again, then open it.",
    "Word 문서 형식이 아니에요. 이름만 .doc 인 다른 파일일 수 있어요.": "This isn't a Word document. It may be another kind of file named .doc.",
    "구형 Word(.doc) 본문을 읽지 못했어요. 손상됐거나 아직 다루지 못하는 형태예요.": "Couldn't read the legacy Word (.doc) body. It may be damaged or in an unsupported form.",
