    "HTML 파일을 직접 열면 내 컴퓨터의 파이썬에 연결할 수 없습니다. ClassDock.exe 로 실행하면 설치된 파이썬을 자동으로 찾습니다.": "When the HTML file is opened directly it can't connect to Python on your computer. Run ClassDock.exe to find installed Python automatically.",
