    "파이썬을 설치하면 자동으로 로컬 실행으로 바뀝니다. 이미 설치했는데도 이 안내가 보이면 아래 순서를 확인해 주세요.": "Once Python is installed, runs switch to local automatically. If you've installed it and still see this, check the steps below.",
    "python.org 에서 파이썬을 설치합니다. 설치 첫 화면의 'Add python.exe to PATH' 를 체크하면 가장 확실합니다.": "Install Python from python.org. Checking 'Add python.exe to PATH' on the first installer screen is the surest way.",
    "설치가 끝나면 아래 '다시 검사' 를 누릅니다. 앱을 껐다 켤 필요는 없습니다.": "When installation finishes, press 'Scan again' below. No need to restart the app.",
    "그래도 찾지 못하면 파이썬을 기본 폴더가 아닌 곳에 설치한 경우입니다. 'Add python.exe to PATH' 를 체크해 다시 설치해 주세요.": "If it's still not found, Python was installed outside the default folder. Reinstall with 'Add python.exe to PATH' checked.",
