    "이 PC의 지속형 PowerShell에서 명령을 실행합니다. 현재 폴더와 변수는 다음 명령에도 유지됩니다. 열려 있는 파이썬 파일들이 이 터미널을 함께 씁니다.": "Runs commands in a persistent PowerShell on this PC. The current folder and variables persist across commands. Open Python files share this terminal.",
