    "이 크롤링은 로컬 Python이 필요합니다. Python을 설치할 때 'Add python.exe to PATH'를 선택한 뒤 ClassDock을 다시 실행해 주세요.": "This scraping needs local Python. Install Python with 'Add python.exe to PATH' selected, then restart ClassDock.",
