    "누적 그래프를 만들지 못했어요.": "Couldn't make the cumulative graph.",
    "‘반응물 -> 생성물’ 로 적으면 계수를 맞춰 드려요. 괄호가 있는 Ca(OH)2 도 됩니다.": "Write 'reactants -> products' and the coefficients are balanced for you. Parentheses like Ca(OH)2 work too.",
