    "반응식 칸에 커서가 있어요 — 원소를 누르면 기호가 커서 자리에 들어갑니다.": "The cursor is in the equation box — click an element to insert its symbol there.",
    "원소를 누르면 번호·기호·이름·원자량 카드가 들어갑니다. 반응식 칸에 커서를 두고 누르면 기호가 그 자리에 적혀요.": "Click an element to insert a card with its number, symbol, name and atomic mass. With the cursor in the equation box, the symbol is typed there instead.",
    "자료를 입력하면 미리보기가 나타나요. 아래 예시를 눌러 시작해도 좋아요.": "Enter data to see a preview. You can also start from an example below.",
    "쉼표·탭·띄어쓰기로 이름과 값을 나눠 적으면 됩니다. 값을 여러 열 적으면 묶음끼리 나란히 비교하고, 표를 복사해 붙여넣어도 돼요.": "Separate names and values with commas, tabs or spaces. Several value columns are compared side by side, and you can paste a copied table.",
    "차트를 만들지 못했어요.": "Couldn't make the chart.",
    "차트 바꾸기": "Update chart",
    "수식 바꾸기": "Update equation",
    "— 눌러서 커서가 있는 식 칸 채우기": "— click to fill the expression box with the cursor",
    "— 눌러서 입력칸 채우기": "— click to fill the input",
