    "원소 이름·기호·번호 검색 (예: 산소, Na, 26)": "Search element name, symbol or number (e.g. oxygen, Na, 26)",
    "넣은 뒤에도 두 번 누르면 다시 고칠 수 있어요. ‘분리’를 누르면 선·글자로 흩어집니다.": "Double-click after inserting to edit again. 'Ungroup' breaks it into lines and text.",
