    "기준점 찍기": "Set reference point",
    "보드를 눌러 대칭·회전·닮음의 기준점을 정합니다": "Click the board to set the reference point for reflection, rotation and dilation",
    "보드에서 기준점이 될 자리를 눌러 주세요.": "Click the spot on the board to use as the reference point.",
    "도형 중심": "Shape center",
    "기준점을 선택한 도형의 중심으로 되돌립니다": "Reset the reference point to the selected shape's center",
    "원본 남기고 사본 만들기": "Keep the original and make a copy",
    "변환하기": "Transform",
    "선택한 도형에 변환을 적용합니다": "Apply the transformation to the selected shape",
    "보드를 눌러 기준점 지정…": "Click the board to set the reference point…",
    "기준점: 보드에 찍은 자리": "Reference point: the spot you clicked",
    "기준점: 도형의 중심": "Reference point: shape center",
    "이미지는 방향을 틀지 않는 평행이동과 닮음만 적용할 수 있어요.": "Only translation and dilation, which don't change orientation, can be applied to images.",
    "자의 눈금 모서리가 대칭축이 됩니다. 자를 옮기면 축도 함께 움직여요.": "The ruler's marked edge becomes the axis of symmetry. Move the ruler to move the axis.",
    "기준점에서 잰 거리가 배율만큼 늘거나 줄어듭니다. 글자 크기와 선 굵기도 함께 바뀝니다.": "Distances from the reference point grow or shrink by the scale factor. Text size and line width change too.",
    "양수는 시계 방향입니다. 글자는 읽을 수 있게 눕히지 않습니다.": "Positive is clockwise. Text stays upright so it remains readable.",
    "선택한 도형을 바꾼 결과를 사본으로 만듭니다.": "Creates the transformed result as a copy of the selected shape.",
    "집중 도구 — 스포트라이트·화면 가리개": "Focus tools — spotlight and screen shade",
    "단계 발표 — 정한 차례대로 하나씩 보여 줍니다 (항목 우클릭 → 발표 단계)": "Step presentation — reveals items one by one in the set order (right-click an item → Presentation step)",
    "이전 단계 (PageUp·←)": "Previous step (PageUp/←)",
    "다음 단계 (PageDown·→)": "Next step (PageDown/→)",
    "단계 발표 끝내기 (Esc)": "End step presentation (Esc)",
    "아직 단계 항목이 하나도 안 보이는 첫 화면": "First screen, before any step items appear",
    "단계 발표 — 항목을 우클릭해 '발표 단계'에서 나타날 차례를 먼저 정하세요": "Step presentation — first right-click items and set their order under 'Presentation step'",
    "자 — 대고 그으면 곧게 그려지고 cm 눈금이 보입니다 (길이 2~40cm 조절)": "Ruler — draw along it for straight lines, with cm marks (length 2–40 cm)",
    "자를 놓았어요. 몸통을 끌어 옮기고, 오른쪽 동그라미로 돌리고, 왼쪽 동그라미를 끌어 길이를 40cm까지 늘립니다.": "Ruler placed. Drag the body to move it, the right circle to rotate, and the left circle to stretch it up to 40 cm.",
    "각도기 — 가운데에서 시작해 그으면 각도가 1°씩 맞춰집니다 (밑변 4~30cm 조절)": "Protractor — drawing from the center snaps to 1° (base 4–30 cm)",
    "각도기를 놓았어요. 가운데 점에서 시작해 그으면 각도가 표시되고, 왼쪽 동그라미를 끌면 크기가 커집니다.": "Protractor placed. Draw from the center point to show the angle; drag the left circle to resize it.",
    "컴퍼스 — 연필 손잡이를 돌리면 호와 원이 그려집니다 (반지름 2~30cm 조절)": "Compass — turn the pencil handle to draw arcs and circles (radius 2–30 cm)",
    "컴퍼스를 놓았어요. 가운데=바늘, 중간 손잡이를 끌면 반지름이 2~30cm로 벌어지고, 끝 손잡이를 돌리면 호가 그려집니다.": "Compass placed. The center is the needle; drag the middle handle to open the radius to 2–30 cm, and turn the end handle to draw an arc.",
    "각도 맞추기 — 직선·화살표를 15°씩 맞춰 긋습니다 (Shift 를 눌러도 같아요)": "Angle snap — lines and arrows snap to 15° (holding Shift does the same)",
    "손그림 정리 — 대충 그린 동그라미·세모·네모를 반듯하게 바꿔 줍니다": "Shape cleanup — turns rough circles, triangles and squares into neat shapes",
    "손그림 정리를 켰어요. 크게 그린 도형만 반듯하게 바꿉니다(글씨는 그대로).": "Shape cleanup on. Only large drawn shapes are straightened (handwriting stays as is).",
    "측정 — 고른 도형의 길이·각도·넓이를 붙입니다(도형을 끌면 값이 따라 바뀜)": "Measure — adds length, angle and area to the selected shape (values update as you drag)",
    "벡터 합성 — 같은 점에서 출발한 두 화살표의 합력을 붙입니다(화살표를 끌면 따라 바뀜)": "Vector sum — adds the resultant of two arrows from the same point (updates as you drag)",
    "변환 — 고른 도형을 대칭·회전·평행이동·닮음으로 바꿉니다": "Transform — reflect, rotate, translate or dilate the selected shape",
    "함수 그래프 — 식을 치면 실제로 계산한 곡선을 넣습니다": "Function graph — type an expression to insert the computed curve",
    "자료 차트 — 표 숫자로 막대·꺾은선·원그래프를 만듭니다": "Data chart — bar, line or pie charts from table numbers",
