    "녹화 리플레이를 자동 복원에 저장했습니다.": "Saved the recorded replay for auto-restore.",
    "녹화 리플레이를 자동 복원에 저장하지 못했습니다.": "Couldn't save the recorded replay for auto-restore.",
    "수업 리플레이가 만들어졌어요. ▶ 재생하거나 저장 버튼으로 .lesson 파일을 남기세요.": "The lesson replay is ready. Press ▶ to play, or Save to keep a .lesson file.",
    "리플레이를 자동 복원 목록에 저장하지 못했어요. 앱을 다시 켜기 전에 저장 버튼으로 .lesson 파일을 남겨 두세요.": "Couldn't add the replay to auto-restore. Save a .lesson file before restarting the app.",
    // 표·PDF·문서·이미지·영상·메모·블록 문서·여러 파일 바꾸기
    "앞선 변환이 끝나기를 기다리는 중…": "Waiting for the previous conversion to finish…",
    "MP4로 변환 중": "Converting to MP4",
