    "일괄 변환 완료 —": "Batch conversion done —",
    "필요한 영상·소리만 호환 형식으로 변환해요": "Converts only the video/audio streams that need it to compatible formats",
    "무료 변환 도구 내려받는 중…": "Downloading the free conversion tool…",
    "설치 완료! 이어서 변환을 시작해요.": "Installed! Starting the conversion.",
    "변환 중지": "Stop conversion",
    "변환을 멈춰요. 만들다 만 파일은 남기지 않아요": "Stops the conversion. Partial files aren't kept",
    "MP4로 변환 준비 중…": "Preparing MP4 conversion…",
    "변환을 중지했어요.": "Conversion stopped.",
    "ffmpeg를 찾지 못했어요. ffmpeg.exe 를 ClassDock.exe 옆에 놓고 다시 시도해 주세요.": "ffmpeg wasn't found. Put ffmpeg.exe next to ClassDock.exe and try again.",
    "영상 변환은 ClassDock.exe 로 실행할 때만 쓸 수 있어요.": "Video conversion is only available when running ClassDock.exe.",
    "변환에는 무료 변환 도구(ffmpeg)가 필요해요. 버튼을 누르면 인터넷에서 약 90MB를 한 번만 내려받아 자동 설치됩니다.": "Conversion needs the free ffmpeg tool. Press the button to download about 90 MB once and install it automatically.",
    "이 파일은 1GB가 넘어요. 폴더째 열면(파일 → 폴더 열기) 크기 제한 없이 변환할 수 있어요. 끌어다 놓은 파일은 앱이 원본 위치를 알 수 없어 통째로 주고받아야 하거든요.": "This file is over 1 GB. Open its folder (File → Open folder) to convert without a size limit — for dragged-in files the app doesn't know the original location, so the whole file has to be passed around.",
    "MP4로 변환 중… 영상 길이에 따라 몇 분 걸릴 수 있어요. 이 탭을 닫지 마세요.": "Converting to MP4… this can take a few minutes depending on the length. Don't close this tab.",
    "영상 다시 인코딩": "Re-encode video",
    "영상을 H.264 호환 형식으로 다시 인코딩해 별도 파일로 저장해요": "Re-encodes the video to compatible H.264 and saves it as a separate file",
    "AVI·WMV·FLV 형식은 대부분 지원되지 않아요.": "AVI, WMV and FLV are mostly unsupported.",
    "파일 안의 코덱에 따라 재생이 안 될 수 있어요.": "It may not play, depending on the codec inside the file.",
    "영상을 먼저 재생하거나 원하는 장면으로 이동해 주세요.": "Play the video first, or move to the scene you want.",
    "이 영상에서는 화면을 캡처할 수 없어요.": "Frames can't be captured from this video.",
