    "(자동 연결)": "(auto-linked)",
    "영상 다시 변환": "Convert video again",
    "화면이 안 나오거나 깨질 때 호환 형식으로 다시 인코딩": "Re-encode to a compatible format if the picture is missing or garbled",
    "라이브러리 로드 실패 — 인터넷 연결을 확인하세요.": "Library failed to load — check your internet connection.",
    "회전된 페이지가 있어 위치가 약간 어긋날 수 있어요.": "Some pages are rotated, so positions may be slightly off.",
    "PDF 를 열지 못했습니다. (암호 걸린 파일은 미지원)": "Couldn't open the PDF. (Password-protected files aren't supported.)",
    "스캔 PDF 글자 인식(OCR) 도구를 인터넷(CDN)에서 받아옵니다(한국어+영어, 약 15~20MB · 최초 1회).\\n문서 내용은 외부로 전송되지 않고 인식은 이 컴퓨터 안에서만 처리돼요.": "Downloads the scanned-PDF text recognition (OCR) tool from the internet (CDN) (Korean + English, about 15–20 MB · first time only).\\nDocument content isn't sent anywhere; recognition runs only on this computer.",
    "받아오기": "Download",
