    "현재 폴더 자동 감지 대기 중입니다. 지원하지 않는 셸에서는 직접 입력하세요. ./는 로그인 홈 폴더입니다.": "Waiting to detect the current folder. In unsupported shells, enter it yourself. ./ is the login home folder.",
