    "Bash 접속에서는 현재 폴더를 자동으로 채웁니다. 직접 입력한 경로는 자동 감지가 덮어쓰지 않습니다. 다른 서버로 다시 SSH 접속했거나 컨테이너 셸에서는 원래 서버 경로를 직접 입력하세요. 같은 이름의 파일은 덮어쓸 수 있습니다.": "With Bash, the current folder is filled in automatically. A path you type isn't overwritten by detection. If you SSH'd onward to another server or are in a container shell, enter the original server's path yourself. Files with the same name may be overwritten.",
