  function t(ko) {
    if (ko == null) return ko;
    if (lang !== "en") return ko;
    var s = String(ko);
    var hit = DICT[s];
    if (hit != null) return hit;
    var trimmed = s.trim();
    if (trimmed !== s && DICT[trimmed] != null) {
      // 앞뒤 공백 보존
      var m = s.match(/^(\s*)([\s\S]*?)(\s*)$/);
      return m[1] + DICT[trimmed] + m[3];
    }
    return translateLabel(s);
  }

