    "'{name}'은(는) 다른 프로그램에서 만든 MusicXML이에요. 원본에 덮어쓰면 이 앱이 읽지 못한 정보(꾸밈음·레이아웃·일부 기호 등)는 사라져요.{label} 원본은 그대로 두고 악보(.msheet) 파일로 따로 저장할 수도 있어요.": "'{name}' is a MusicXML made by another program. Overwriting it drops anything this app couldn't read (grace notes, layout, some symbols).{label} You can also leave the original alone and save a separate score (.msheet) file.",
