    "이 결과는 {name} 을(를) 고칠 수 있습니다 — 칸을 두 번 누르거나 F2, 또는 바로 타자를 치면 그 자리에서 고칩니다(Enter 아래로 · Tab 옆으로 · Esc 취소). 긴 값·여러 줄 값·NULL 은 값 창이 대신 열립니다. 행을 골라 ‘행 삭제’, 새 행은 ‘행 추가’ 로 담고, 담은 변경은 ‘적용’ 을 눌러야 서버에 갑니다.": "These results can edit {name} — double-click a cell, press F2 or just type to edit in place (Enter down · Tab across · Esc cancel). Long, multi-line or NULL values open the value window instead. Select rows for 'Delete row', use 'Add row' for new rows, and press 'Apply' to send staged changes to the server.",
